    // -------------------------------------------------------------------------
    // Planters and low-poly plants
    // -------------------------------------------------------------------------

    function makePlant(x, z, phase) {
      const planter = addBox(
        1.25,
        0.12,
        0.82,
        materials.rim,
        new THREE.Vector3(x, 0.06, z)
      );
      scene.add(planter);

      const soil = addBox(
        1.1,
        0.035,
        0.67,
        materials.soil,
        new THREE.Vector3(x, 0.135, z)
      );
      scene.add(soil);

      const stem = addCylinder(
        0.025,
        0.035,
        0.42,
        materials.stem,
        new THREE.Vector3(x, 0.34, z),
        8
      );
      scene.add(stem);

      const leafGeometry = new THREE.SphereGeometry(1, 10, 7);

      const leaves = [
        [-0.13, 0.48, 0, -0.35, 0.15],
        [0.12, 0.53, 0, 0.38, -0.12],
        [-0.08, 0.68, 0.02, -0.18, 0.2],
        [0.09, 0.73, -0.02, 0.2, -0.18],
        [0, 0.86, 0, 0, 0]
      ];

      leaves.forEach((leaf, index) => {
        const mesh = new THREE.Mesh(
          leafGeometry,
          index % 2 === 0 ? materials.leaf : materials.leafLight
        );

        mesh.position.set(
          x + leaf[0],
          0.34 + leaf[1],
          z + leaf[2]
        );
        mesh.scale.set(0.2, 0.055, 0.1);
        mesh.rotation.set(
          leaf[3],
          index * 0.55,
          leaf[4]
        );
        mesh.castShadow = true;
        scene.add(mesh);
      });
    }

    emitterXs.forEach((x, index) => {
      makePlant(x, 1.85 + (index % 2) * 0.12, index * 0.73);
    });

    // -------------------------------------------------------------------------
    // Flow animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    let flowEnabled = true;

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      const time = clock.elapsedTime;

      if (flowEnabled) {
        for (const flow of flowItems) {
          const t = (time * flow.speed + flow.offset) % 1;
          flow.curve.getPointAt(t, flow.mesh.position);
        }

        emitterDrops.forEach((drop, index) => {
          drop.position.y =
            0.535 + Math.sin(time * 2.1 + index * 0.8) * 0.018;
          drop.scale.setScalar(
            0.85 + Math.sin(time * 2.1 + index * 0.8) * 0.25
          );
        });

        emitterLEDs.forEach((led, index) => {
          led.material.emissiveIntensity =
            1.25 + Math.sin(time * 2.4 + index * 0.65) * 0.45;
        });
      }

      updateCamera();
      renderer.render(scene, camera);
    }

    renderer.setAnimationLoop(animate);

    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, zoom, keyboard, and touch pinch
    // -------------------------------------------------------------------------

    const pointers = new Map();
    let lastCenter = null;
    let lastPinchDistance = 0;

    function pointerCenter() {
      const values = [...pointers.values()];
      return {
        x: values.reduce((sum, p) => sum + p.x, 0) / values.length,
        y: values.reduce((sum, p) => sum + p.y, 0) / values.length
      };
    }

    function pointerDistance() {
      const values = [...pointers.values()];
      if (values.length < 2) return 0;

      return Math.hypot(
        values[0].x - values[1].x,
        values[0].y - values[1].y
      );
    }

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        lastCenter = {
          x: event.clientX,
          y: event.clientY
        };
      } else if (pointers.size === 2) {
        lastCenter = pointerCenter();
        lastPinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      const previous = pointers.get(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        const dx = event.clientX - previous.x;
        const dy = event.clientY - previous.y;

        view.theta -= dx * 0.006;
        view.phi -= dy * 0.005;
        lastCenter = {
          x: event.clientX,
          y: event.clientY
        };
      } else if (pointers.size === 2) {
        const center = pointerCenter();
        const distance = pointerDistance();

        if (lastPinchDistance > 0 && distance > 0) {
          view.radius *= lastPinchDistance / distance;
          view.radius = THREE.MathUtils.clamp(
            view.radius,
            5.2,
            18
          );
        }

        view.theta -= (center.x - lastCenter.x) * 0.005;
        view.phi -= (center.y - lastCenter.y) * 0.005;

        lastCenter = center;
        lastPinchDistance = distance;
      }
    });

    function endPointer(event) {
      pointers.delete(event.pointerId);

      if (pointers.size === 1) {
        const remaining = [...pointers.values()][0];
        lastCenter = { x: remaining.x, y: remaining.y };
      } else {
        lastCenter = null;
        lastPinchDistance = 0;
      }
    }

    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);
    canvas.addEventListener("lostpointercapture", endPointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        view.radius *= Math.exp(event.deltaY * 0.001);
        view.radius = THREE.MathUtils.clamp(
          view.radius,
          5.2,
          18
        );
      },
      { passive: false }
    );

    canvas.addEventListener("dblclick", resetView);

    canvas.addEventListener("keydown", (event) => {
      const key = event.key;

      if (key === "ArrowLeft") view.theta -= 0.08;
      if (key === "ArrowRight") view.theta += 0.08;
      if (key === "ArrowUp") view.phi -= 0.06;
      if (key === "ArrowDown") view.phi += 0.06;
      if (key === "+" || key === "=") view.radius *= 0.9;
      if (key === "-" || key === "_") view.radius *= 1.1;

      view.phi = THREE.MathUtils.clamp(view.phi, 0.35, 1.45);
      view.radius = THREE.MathUtils.clamp(view.radius, 5.2, 18);
      event.preventDefault();
    });

    function resetView() {
      Object.assign(view, defaultView);
      updateCamera();
    }

    flowButton.addEventListener("click", () => {
      flowEnabled = !flowEnabled;
      flowButton.textContent = flowEnabled ? "Pause flow" : "Resume flow";
      statusDot.classList.toggle("paused", !flowEnabled);
    });

    labelButton.addEventListener("click", () => {
      emitterLabels.visible = !emitterLabels.visible;
      labelButton.textContent = emitterLabels.visible
        ? "Hide labels"
        : "Show labels";
    });

    resetButton.addEventListener("click", resetView);

    // -------------------------------------------------------------------------
    // Resize
    // -------------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    loading.remove();
  </script>
